rep("  if (kind === 'kn-order') {\n    const type = Math.random() < 0.5 ? 'sharp' : 'flat', order","  if (kind === 'kn-ordS' || kind === 'kn-ordF') {\n    const type = kind === 'kn-ordS' ? 'sharp' : 'flat', order")
